/*
 * prog59_rule110.c
 *
 * Re‑implementation of the original program that was compiled,
 * then heavily obfuscated.  The original program implements a
 * Rule‑110 cellular automaton.
 *
 * Usage:
 *     prog59_rule110 <binary‑string> <steps>
 *
 *   <binary‑string>  – a string of ‘0’ and ‘1’ characters,
 *                      length must be between 1 and 60 inclusive.
 *   <steps>          – a non‑negative integer (max 200) that
 *                      tells how many generations to output.
 *
 * The program prints the evolution of the automaton, one generation
 * per line, using the same format as the original binary.  On any
 * error it prints exactly the string "INVALID_INPUT" followed by a
 * newline (the behaviour of `puts`).
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_LEN 60
#define MAX_STEPS 200

/* Rule‑110 lookup table.
 * Index is the 3‑bit neighbourhood (left<<2 | centre<<1 | right)
 * where the bits are interpreted as 0/1.
 * The table stores the resulting bit (0 or 1).
 *
 * 111 110 101 100 011 010 001 000
 *   0   1   1   0   1   1   1   0
 */
static const unsigned char RULE110[8] = {
    0, /* 000 */
    1, /* 001 */
    1, /* 010 */
    1, /* 011 */
    0, /* 100 */
    1, /* 101 */
    1, /* 110 */
    0  /* 111 */
};

/* Print the current row (array of 0/1) as characters '0'/'1'. */
static void print_row(const unsigned char *row, size_t len)
{
    for (size_t i = 0; i < len; ++i)
        putchar(row[i] + '0');
    putchar('\n');
}

/* Compute the next generation according to Rule‑110.
 * Cells outside the interval [0, len) are considered 0.
 */
static void next_generation(const unsigned char *cur,
                            unsigned char *next,
                            size_t len)
{
    for (size_t i = 0; i < len; ++i) {
        unsigned int left   = (i == 0) ? 0 : cur[i - 1];
        unsigned int centre = cur[i];
        unsigned int right  = (i + 1 == len) ? 0 : cur[i + 1];
        unsigned int idx = (left << 2) | (centre << 1) | right;
        next[i] = RULE110[idx];
    }
}

/* Validate that a string consists only of ‘0’ and ‘1’. */
static int is_binary_string(const char *s, size_t len)
{
    for (size_t i = 0; i < len; ++i)
        if (s[i] != '0' && s[i] != '1')
            return 0;
    return 1;
}

int main(int argc, char **argv)
{
    /* ----- argument count check ----- */
    if (argc < 3) {
        puts("INVALID_INPUT");
        return 0;
    }

    /* ----- first argument: initial row ----- */
    const char *init_str = argv[1];
    size_t len = strlen(init_str);

    if (len == 0 || len > MAX_LEN || !is_binary_string(init_str, len)) {
        puts("INVALID_INPUT");
        return 0;
    }

    /* ----- second argument: number of steps ----- */
    char *endptr;
    long steps_long = strtol(argv[2], &endptr, 10);
    if (endptr == argv[2] || *endptr != '\0' || steps_long < 0) {
        puts("INVALID_INPUT");
        return 0;
    }
    if (steps_long > MAX_STEPS)
        steps_long = MAX_STEPS;          /* the original caps at 200 */

    int steps = (int)steps_long;

    /* ----- initialise the two rows ----- */
    unsigned char row0[MAX_LEN] = {0};
    unsigned char row1[MAX_LEN] = {0};

    for (size_t i = 0; i < len; ++i)
        row0[i] = (unsigned char)(init_str[i] - '0');

    /* ----- simulation ----- */
    unsigned char *cur = row0;
    unsigned char *next = row1;

    for (int gen = 0; gen < steps; ++gen) {
        print_row(cur, len);
        next_generation(cur, next, len);
        unsigned char *tmp = cur;
        cur = next;
        next = tmp;
    }

    return 0;
}
